    Node* next;
    Node(int data){
        this->data = data;
        next = NULL;
    }
};

// Queue class to define the queue data structure and its methods
class Queue {
private:
    Node *head, *tail;
public:
    Queue(){
        head = tail = NULL;
    }

    // Method to check if the queue is empty or not
    bool isEmpty(){
        return head == NULL;
    }

    // Method to add an element to the queue
    void enqueue(int data){
        Node* temp = new Node(data);

        // If the queue is empty, add the new node as the head
        if(isEmpty()){
            head = tail = temp;
            return;
        }

        // Otherwise, add the new node to the end of the queue
        tail->next = temp;
        tail = temp;
    }

    // Method to remove an element from the queue
    void dequeue(){
        // If the queue is empty, throw an error
        if(isEmpty()){
            throw runtime_error("Error: Queue is Empty");
        }

        // Otherwise, remove the head of the queue and update the head pointer
        Node* temp = head;
        head = head->next;

        // If the queue becomes empty, update the tail pointer as well
        if(head == NULL){
            tail = NULL;
        }

        delete temp;
    }

    // Method to display the elements in the queue
    void display(){
        // If the queue is empty, print a message and return
        if(isEmpty()){
            cout << "Queue is Empty!" << endl;
            return;
        }

        // Traverse the queue and display each element
        Node* temp = head;
        cout << "Queue: ";
        while(temp != NULL){
            cout << temp->data << " ";
            temp = temp->next;
        }

        cout << endl;
    }
};

