```typescript
import * as yup from 'yup';

interface FormData {
  name: string;
  email: string;
  age: number;
  hobbies: string[];
}

interface ValidationErrors {
  [key: string]: string | undefined;
}

export class FormValidator {
  private schema: yup.SchemaOf<FormData>;

  constructor() {
    this.schema = yup.object().shape({
      name: yup.string().required(),
      email: yup.string().email().required(),
      age: yup.number().required().positive().integer(),
      hobbies: yup.array().of(yup.string().required()).min(1),
    });
  }

  public async validate(formData: FormData): Promise<ValidationErrors> {
    try {
      await this.schema.validate(formData, { abortEarly: false });
      return {};
    } catch (error) {
      return this.formatErrors(error);
    }
  }

  private formatErrors(error: yup.ValidationError): ValidationErrors {
    const validationErrors: ValidationErrors = {};

    error.inner.forEach((err) => {
      if (validationErrors[err.path] === undefined) {
        validationErrors[err.path] = err.message;
      }
    });

    return validationErrors;
  }
}
```

